/*
 * Progressive enhancement only. Every action the board offers works without this
 * file: forms submit, links navigate, spoilers can be revealed by CSS :target
 * fallback. The original inlined its JavaScript as onclick="javascript:..."
 * attributes generated by PHP string concatenation, which is why the post filter
 * had to special-case a specific confirm() dialog to avoid stripping it.
 */
(function () {
    'use strict';

    /* ------------------------------------------------------------ confirms */

    // Destructive POST forms carry data-confirm rather than an inline handler.
    document.addEventListener('submit', function (event) {
        var form = event.target;
        if (!(form instanceof HTMLFormElement)) return;

        var message = form.getAttribute('data-confirm');
        if (message && !window.confirm(message)) {
            event.preventDefault();
        }
    });

    /* ------------------------------------------------------------ spoilers */

    document.addEventListener('click', function (event) {
        var label = event.target.closest('.spoiler-label');
        if (!label) return;

        var spoiler = label.closest('.spoiler');
        if (spoiler) spoiler.classList.toggle('revealed');
    });

    /* ------------------------------------------------- formatting toolbar */

    /**
     * Wraps the selection in a tag pair, or inserts at the caret when nothing is
     * selected. The "|" in data-wrap marks where the caret should end up.
     */
    function applyWrap(textarea, spec) {
        var parts = spec.split('|');
        var before = parts[0] || '';
        var after = parts[1] || '';

        var start = textarea.selectionStart;
        var end = textarea.selectionEnd;
        var selected = textarea.value.slice(start, end);

        textarea.setRangeText(before + selected + after, start, end, 'end');

        // With no selection, drop the caret between the tags so typing continues
        // inside them.
        if (start === end) {
            var caret = start + before.length;
            textarea.setSelectionRange(caret, caret);
        }

        textarea.focus();
    }

    function insertText(textarea, text) {
        var start = textarea.selectionStart;
        textarea.setRangeText(text, start, textarea.selectionEnd, 'end');
        textarea.focus();
    }

    document.querySelectorAll('[data-toolbar-for]').forEach(function (toolbar) {
        var targetId = toolbar.getAttribute('data-toolbar-for');
        var textarea = document.getElementById(targetId)
            || toolbar.parentElement.querySelector('textarea');

        if (!textarea) return;

        toolbar.addEventListener('click', function (event) {
            var button = event.target.closest('button');
            if (!button) return;

            var wrap = button.getAttribute('data-wrap');
            var insert = button.getAttribute('data-insert');

            if (wrap) {
                event.preventDefault();
                applyWrap(textarea, wrap);
            } else if (insert) {
                event.preventDefault();
                insertText(textarea, insert);
            }
        });
    });

    /* ------------------------------------------- collection add (polls etc) */

    document.querySelectorAll('.collection-add').forEach(function (button) {
        button.addEventListener('click', function () {
            var container = button.previousElementSibling;
            if (!container || !container.classList.contains('collection')) return;

            var prototype = container.getAttribute('data-prototype');
            if (!prototype) return;

            var index = container.querySelectorAll('.collection-item').length;
            var item = document.createElement('div');
            item.className = 'collection-item';
            item.innerHTML = prototype.replace(/__name__/g, String(index));
            container.appendChild(item);
        });
    });

    /* -------------------------------------------------- select-all checkbox */

    document.querySelectorAll('[data-check-all]').forEach(function (master) {
        var scope = master.closest('form');
        if (!scope) return;

        master.addEventListener('change', function () {
            scope.querySelectorAll('input[type="checkbox"][name="selected[]"]')
                .forEach(function (box) { box.checked = master.checked; });
        });
    });
})();

/* ------------------------------------------------------- member type-ahead
 *
 * Fills the datalist behind a [data-member-picker] field from the lookup
 * endpoint. Purely additive: the field is a plain text box that the server
 * resolves by name, so with this file blocked the form still works - it just
 * stops suggesting.
 */
(function () {
    'use strict';

    var fields = document.querySelectorAll('[data-member-picker]');
    if (!fields.length || typeof window.fetch !== 'function') return;

    Array.prototype.forEach.call(fields, function (field) {
        var endpoint = field.getAttribute('data-member-picker');
        var list = document.getElementById(field.getAttribute('list'));
        if (!endpoint || !list) return;

        var timer = null;
        var lastQuery = null;
        var inFlight = null;

        field.addEventListener('input', function () {
            var query = field.value.trim();

            // Two characters is where the endpoint starts answering; below that
            // every member on the board would match and the list is noise.
            if (query.length < 2 || query === lastQuery) return;

            window.clearTimeout(timer);
            timer = window.setTimeout(function () {
                lastQuery = query;

                // A slow reply for an abandoned prefix must not overwrite the
                // suggestions for what is now in the box.
                if (inFlight) inFlight.abort();
                inFlight = typeof AbortController === 'function' ? new AbortController() : null;

                window.fetch(endpoint + '?q=' + encodeURIComponent(query), {
                    headers: { Accept: 'application/json' },
                    credentials: 'same-origin',
                    signal: inFlight ? inFlight.signal : undefined
                })
                    .then(function (response) {
                        return response.ok ? response.json() : [];
                    })
                    .then(function (matches) {
                        if (query !== lastQuery) return;

                        list.textContent = '';
                        matches.forEach(function (match) {
                            var option = document.createElement('option');
                            option.value = match.name;
                            list.appendChild(option);
                        });
                    })
                    .catch(function () {
                        // An aborted or failed lookup just means no suggestions.
                    });
            }, 200);
        });
    });
})();

/* ------------------------------------------------- timezone autodetection
 *
 * The original asked members to enter their offset from board time as a number
 * of hours - a question with no stable answer, since it changes twice a year
 * under daylight saving, and one most people would rather not work out.
 *
 * The browser already knows the answer. If the member has never chosen a zone
 * (the field still reads UTC), preselect whatever the browser reports and say
 * so, rather than changing it silently. If they have chosen one, leave it be.
 */
(function () {
    'use strict';

    var select = document.querySelector('select[data-timezone-detect]');
    if (!select || typeof Intl === 'undefined' || !Intl.DateTimeFormat) return;

    var detected;
    try {
        detected = Intl.DateTimeFormat().resolvedOptions().timeZone;
    } catch (e) {
        return;
    }
    if (!detected) return;

    // Only act when the field is still at the default, so an explicit choice is
    // never overwritten.
    if (select.value && select.value !== 'UTC') return;

    var match = Array.prototype.find.call(select.options, function (option) {
        return option.value === detected;
    });
    if (!match || select.value === detected) return;

    select.value = detected;

    var note = document.createElement('span');
    note.className = 'form-help timezone-detected';
    note.textContent = 'Detected from your browser: ' + detected + '. Change it if that is wrong.';
    select.insertAdjacentElement('afterend', note);
})();
